import json
events=[]
def number(s):
 events.append(('number',s)); return int(s)
def pairs(value):
 events.append(('pairs',[k for k,v in value])); return ('pairs',value)
def wrong(value):raise AssertionError('object_hook')
value=json.loads('{"k":[{},{"x":1,"x":2}],"k":null}',parse_int=number,object_pairs_hook=pairs,object_hook=wrong)
print(events,value)

import json
for document in ['[{},[1,{"x":[]}]]','[{},[1,{"x":}', '[1,]', '{"x":1,}', '{"x" 2}', '[[', '{', '{"x":', '[1', '{"x":1']:
 events=[]
 def number(s):events.append(s);return int(s)
 def pairs(p):events.append([k for k,v in p]);return dict(p)
 prefix='😀 ignored '
 source=prefix+document+' tail'
 try:
  value,end=json.JSONDecoder(parse_int=number,object_pairs_hook=pairs).raw_decode(source,len(prefix))
  print(value,end,events)
 except json.JSONDecodeError as e:print(e.pos,e.doc is source,events)

