import json
for document in ['01','-01','1.','2e','-3e+','1e-2','NaN','Infinity','-Infinity']:
 events=[]
 def number(s):events.append(('int',s));return int(s)
 def floating(s):events.append(('float',s));return float(s)
 def constant(s):events.append(('constant',s));return s
 value,end=json.JSONDecoder(parse_int=number,parse_float=floating,parse_constant=constant).raw_decode(document)
 print(value,end,events)
